n.exploreUrl:
@js:
let all = [];
var url = 'https://novel.cooks.tw/api/novel/keywords/map?lang=zh-CN';
var res = java.ajax(url);
res = JSON.parse(res);
res = res.data;
res.forEach(x => {
  all.push({
    "title": x.keyword,
    "url": `/api/novel/keyword/${x.keyword_id}?page={{page}}&limit=20`,
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": 0.25
    }
  });
});
result = JSON.stringify(all);

ruleBookInfo.init:
@js:
(function(result){
    result = JSON.parse(result);
    const data = result.data;
    let articleid = data.articleid;
    cache.putMemory('articleid', articleid);

    return data;
})(result);
